<?php declare(strict_types=1);$components=dirname(__DIR__,2).'/components';$e=static fn(mixed$v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$range=$report['range'];ob_start();$breadcrumbItems=[['label'=>'Dashboard','url'=>'/dashboard'],['label'=>'Administration','url'=>'/admin'],['label'=>'Call Log Reports','url'=>'/admin/call-log-reports'],['label'=>'Facebook Performance Report','current'=>true]];require$components.'/breadcrumb.php';$heading='Facebook Performance Report';$description='Facebook call performance by property for the selected reporting period.';$eyebrow='Administration';$actionsHtml='';require$components.'/page-header.php';if($range->errors!==[]):?><div class="alert gateway-alert gateway-alert--danger" role="alert"><?php foreach($range->errors as$message):?><div><?=$e($message)?></div><?php endforeach?></div><?php endif?><form class="gateway-form-card mb-3" method="get" action="/admin/call-log-reports/facebook-performance"><div class="row g-3 align-items-end"><label class="form-label col-12 col-md-4 mb-0">From Date<input class="form-control mt-1" type="date" name="from" value="<?=$e($range->fromDate)?>" required></label><label class="form-label col-12 col-md-4 mb-0">To Date<input class="form-control mt-1" type="date" name="to" value="<?=$e($range->toDate)?>" required></label><div class="col-12 col-md-4"><button class="btn gateway-button gateway-button--primary" type="submit">View Report</button></div></div></form><?php if($range->valid()):?><p class="mb-3" role="status"><strong>Reporting Period:</strong> <?=$e($report['period'])?></p><div class="table-responsive"><table class="table gateway-directory-table"><thead><tr><th scope="col">Property</th><th scope="col" class="text-end">Total Calls</th><th scope="col" class="text-end">No Answer</th><th scope="col" class="text-end">Answered</th><th scope="col" class="text-end">Percent Answered</th></tr></thead><tbody><?php foreach($report['rows']as$row):?><tr><th scope="row"><?=$e($row['property_name'])?></th><td class="text-end"><?=number_format($row['total_calls'])?></td><td class="text-end"><?=number_format($row['no_answer'])?></td><td class="text-end"><?=number_format($row['answered'])?></td><td class="text-end"><?=$row['percent_answered']===null?'':$e($row['percent_answered']).'%'?></td></tr><?php endforeach?></tbody><tfoot><tr class="fw-semibold"><th scope="row">Company Totals</th><td class="text-end"><?=number_format($report['totals']['total_calls'])?></td><td class="text-end"><?=number_format($report['totals']['no_answer'])?></td><td class="text-end"><?=number_format($report['totals']['answered'])?></td><td class="text-end"><?=$report['totals']['percent_answered']===null?'':$e($report['totals']['percent_answered']).'%'?></td></tr></tfoot></table></div><?php else:?><p class="text-body-secondary">Choose a From Date and To Date to generate the report.</p><?php endif;$contentHtml=(string)ob_get_clean();$pageTitle='Facebook Performance Report — NPM Gateway';$navbarItems=\NpmGateway\Support\Navigation::forRoute('/admin/call-log-reports/facebook-performance',dirname(__DIR__,4));$navbarUserLabel=$user->displayName;$navbarUserContext='@'.$user->username;require dirname(__DIR__,2).'/layouts/app.php';
